const input = $input.all();

let tickets = [];
for (const item of input) {
  const data = item.json;

  if (Array.isArray(data)) {
    tickets.push(...data);
  } else if (Array.isArray(data.items)) {
    tickets.push(...data.items);
  } else if (Array.isArray(data.tickets)) {
    tickets.push(...data.tickets);
  } else if (Array.isArray(data.data)) {
    tickets.push(...data.data);
  } else if (data && data._id) {
    tickets.push(data);
  }
}

const now = new Date().toISOString();

return tickets.map((t) => {
  return {
    json: {
      entity_type: 'ticket',
      entity_id: String(t._id),
      source_id: `ticket:${String(t._id)}`,
      id_itil: t['ID-ITIL'] || null,
      title: t.asunto || null,
      status: t.estado || null,
      description_html: t.descripcion_html || '',
      resolution_html: t.resolucion_html || '',
      comments: Array.isArray(t.comentarios) ? t.comentarios : [],
      history: Array.isArray(t.historial) ? t.historial : [],
      attachments: Array.isArray(t.adjuntos) ? t.adjuntos : [],
      category: t.categoria || null,
      subcategory: t.subcategoria || null,
      article: t.articulo || null,
      priority: t.prioridad || null,
      created_at: t.created_at || null,
      updated_at: t.fecha_actualizacion || null,
      version_key: String(t.fecha_actualizacion || ''),
      snapshot_status: 'active',
      last_seen_at: now,
      raw: t
    }
  };
});

const currentItems = $('Code - Normalize Current Tickets').all().map(i => i.json);

const previousItems = $('MongoDB - Load Previous Tickets Snapshot')
  .all()
  .map(i => i.json)
  .filter(i => i && i.entity_id);

const currentMap = new Map();
const previousMap = new Map();

for (const item of currentItems) {
  currentMap.set(item.entity_id, item);
}

for (const item of previousItems) {
  previousMap.set(item.entity_id, item);
}

const results = [];

for (const [entityId, current] of currentMap.entries()) {
  const previous = previousMap.get(entityId);

  if (!previous) {
    results.push({
      json: {
        entity_type: 'ticket',
        entity_id: entityId,
        diff_type: 'created',
        current,
        previous: null
      }
    });
    continue;
  }

  if (current.version_key !== previous.version_key) {
    results.push({
      json: {
        entity_type: 'ticket',
        entity_id: entityId,
        diff_type: 'updated',
        current,
        previous
      }
    });
  }
}

for (const [entityId, previous] of previousMap.entries()) {
  if (!currentMap.has(entityId)) {
    results.push({
      json: {
        entity_type: 'ticket',
        entity_id: entityId,
        diff_type: 'deleted',
        current: null,
        previous
      }
    });
  }
}

// 🔥 CLAVE: evitar flujo muerto
if (results.length === 0) {
  return [
    {
      json: {
        entity_type: 'ticket',
        diff_type: 'no_changes'
      }
    }
  ];
}

return results;

const row = $input.item.json;

let eventType = null;
let eventTs = new Date().toISOString();
let versionKey = null;
let payload = null;

if (row.diff_type === 'created') {
  eventType = 'ticket_created';
  eventTs = row.current?.updated_at || row.current?.created_at || eventTs;
  versionKey = row.current?.version_key || null;
  payload = row.current;
}

if (row.diff_type === 'updated') {
  eventType = 'ticket_updated';
  eventTs = row.current?.updated_at || eventTs;
  versionKey = row.current?.version_key || null;
  payload = {
    current: row.current,
    previous: row.previous
  };
}

if (row.diff_type === 'deleted') {
  eventType = 'ticket_deleted';
  versionKey = row.previous?.version_key || null;
  payload = row.previous;
}

return {
  json: {
    entity_type: 'ticket',
    entity_id: row.entity_id,
    event_type: eventType,
    event_ts: eventTs,
    version_key: versionKey,
    correlation_key: `ticket|${row.entity_id}|${eventType}|${eventTs}`,
    payload
  }
};

const ev = $input.item.json;

if (ev.event_type === 'ticket_created') {
  const data = ev.payload;

  return {
    json: {
      op: 'upsert',
      entity_type: 'ticket',
      entity_id: ev.entity_id,
      source_id: data.source_id,
      version_key: ev.version_key,
      status: data.status || null,
      title: data.title || null,
      description_html: data.description_html || '',
      created_at: data.created_at || null,
      updated_at: data.updated_at || null,
      last_seen_at: new Date().toISOString(),
      id_itil: data.id_itil || null,
      category: data.category || null,
      priority: data.priority || null,
      has_attachments: Array.isArray(data.attachments) ? data.attachments.length > 0 : false,
      raw: data.raw
    }
  };
}

if (ev.event_type === 'ticket_updated') {
  const data = ev.payload.current;

  return {
    json: {
      op: 'upsert',
      entity_type: 'ticket',
      entity_id: ev.entity_id,
      source_id: data.source_id,
      version_key: ev.version_key,
      status: data.status || null,
      title: data.title || null,
      description_html: data.description_html || '',
      created_at: data.created_at || null,
      updated_at: data.updated_at || null,
      last_seen_at: new Date().toISOString(),
      id_itil: data.id_itil || null,
      category: data.category || null,
      priority: data.priority || null,
      has_attachments: Array.isArray(data.attachments) ? data.attachments.length > 0 : false,
      raw: data.raw
    }
  };
}

if (ev.event_type === 'ticket_deleted') {
  return {
    json: {
      op: 'delete',
      entity_type: 'ticket',
      entity_id: ev.entity_id,
      source_id: `ticket:${ev.entity_id}`
    }
  };
}

return {
  json: {
    op: 'ignore'
  }
};

const ev = $input.item.json;
const data = ev.payload;

return {
  json: {
    event_type: ev.event_type,
    entity_type: 'ticket',
    entity_id: ev.entity_id,
