const ctx = $('Code - Preparar Contexto Ticket').first().json;
const data = $input.item.json;

const stripHtml = (html = '') => {
  return String(html)
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n\n')
    .replace(/<\/h[1-6]>/gi, '\n\n')
    .replace(/<li>/gi, '- ')
    .replace(/<\/li>/gi, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/\n\s*\n\s*\n+/g, '\n\n')
    .trim();
};

const redact = (text = '') => {
  return String(text)
    .replace(/\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/gi, '[email]')
    .replace(/\b(?:\+?\d{1,3}[\s-]?)?(?:\d[\s-]?){7,15}\b/g, '[phone]');
};

const idItil = data['ID-ITIL'] || ctx.id_itil || null;
const title = data.asunto || ctx.title || '';
const status = data.estado || ctx.status || null;
const priority = data.prioridad || null;
const category = data.categoria || null;
const subcategory = data.subcategoria || null;
const article = data.articulo || null;

const descriptionText = redact(stripHtml(data.descripcion_html || ''));
const resolutionText = redact(stripHtml(data.resolucion_html || ''));

const comments = Array.isArray(data.comentarios) ? data.comentarios : [];
const history = Array.isArray(data.historial) ? data.historial : [];
const attachments = Array.isArray(data.adjuntos) ? data.adjuntos : [];

const commentsText = comments
  .map((c) => {
    const date = c.created_at || c.fecha || '';
    const author = c.autor || c.usuario || c.user_name || '';
    const body = redact(stripHtml(c.comentario_html || c.comentario || ''));
    return [date ? `[${date}]` : '', author ? `[${author}]` : '', body]
      .filter(Boolean)
      .join(' ');
  })
  .filter(Boolean);

const historyText = history
  .map((h) => {
    const date = h.created_at || h.fecha || '';
    const type = h.event_type || '';
    const message = redact(stripHtml(h.message || ''));
    return ['-', date ? `[${date}]` : '', type ? `${type}:` : '', message]
      .filter(Boolean)
      .join(' ');
  })
  .filter(Boolean);

const content = [
  idItil ? `[TICKET] ${idItil}` : '[TICKET]',
  `ID interno: ${ctx.ticket_id}`,
  status ? `Estado: ${status}` : '',
  priority ? `Prioridad: ${priority}` : '',
  category ? `Categoría: ${category}` : '',
  subcategory ? `Subcategoría: ${subcategory}` : '',
  article ? `Artículo: ${article}` : '',
  title ? `Asunto: ${title}` : '',
  descriptionText ? `Descripción:\n${descriptionText}` : '',
  resolutionText ? `Resolución:\n${resolutionText}` : '',
  commentsText.length ? `Comentarios:\n${commentsText.map(x => `- ${x}`).join('\n')}` : '',
  historyText.length ? `Historial:\n${historyText.join('\n')}` : ''
].filter(Boolean).join('\n\n');

return {
  json: {
    content,
    metadata: {
      source_id: ctx.source_id,
      entity_type: 'ticket',
      title,
      file_name: null,
      version_key: ctx.version_key,
      document_origin: 'tickets_api',
      updated_at: ctx.updated_at,
      status: status || 'active',
      id_itil: idItil,
      category,
      priority,
      has_attachments: attachments.length > 0
    }
  }
};

